export function loadRuntimeConfig(env) {
  return { config: { ...env }, summary: { ...env } };
}

import assert from "node:assert/strict";
import { loadRuntimeConfig } from "./config.js";

const result = loadRuntimeConfig({
  NODE_ENV: "production",
  PORT: "3000",
  DATABASE_URL: "postgres://orders-db/orders",
  PAYMENTS_API_TOKEN: "token-do-not-log",
});
assert.deepEqual(result.config, {
  nodeEnv: "production",
  port: 3000,
  databaseUrl: "postgres://orders-db/orders",
  paymentsApiToken: "token-do-not-log",
});
assert.deepEqual(result.summary, {
  nodeEnv: "production",
  port: 3000,
  databaseUrlPresent: true,
  paymentsApiTokenPresent: true,
});
assert.equal(JSON.stringify(result.summary).includes("token-do-not-log"), false);
assert.equal(JSON.stringify(result.summary).includes("postgres://"), false);
for (const env of [
  { NODE_ENV: "development", PORT: "3000", DATABASE_URL: "db", PAYMENTS_API_TOKEN: "token" },
  { NODE_ENV: "production", PORT: "zero", DATABASE_URL: "db", PAYMENTS_API_TOKEN: "token" },
  { NODE_ENV: "production", PORT: "3000", DATABASE_URL: "", PAYMENTS_API_TOKEN: "token" },
  { NODE_ENV: "production", PORT: "3000", DATABASE_URL: "db" },
]) {
  assert.throws(() => loadRuntimeConfig(env));
}
console.log("runtime config contract passed");
